  function recordMeta(r){const s=receipt(r);return `${esc(s.adapter?name(s.adapter)+' ← '+name(r.source):name(r.source))} · ${esc(sourceState(s.state))} · ${s.stamp?esc(s.label+' '+dateStamp(s.stamp)):'undated · update time unknown'}`;}
